-- Seed ROOM_TYPE
INSERT INTO ROOM_TYPE (id, name, capacity, description) VALUES
(1, 'Standard Single', 1, 'Ideelt til solo-rejsende. Klassisk indretning mod rolig gårdhave.'),
(2, 'Grand Lit', 2, 'Lidt større enkeltværelse eller kompakt dobbeltværelse (dobbelt økonomi).'),
(3, 'Standard Double', 2, 'Velegnet til par eller forretningsrejsende med god arbejdsplads.'),
(4, 'Superior Double', 2, 'Rummeligere dobbeltværelse med mere luksuriøse faciliteter og udsigt.'),
(5, 'Junior Suite', 3, 'Unikke værelser med ekstra opholdsplads, historisk inspiration eller moderne stil.'),
(6, 'Spa Executive', 2, 'Suiter med fokus på wellness, boblebad og fri adgang til Ni''mat Spa.'),
(7, 'Suite', 4, 'Store, luksuriøse suiter med separat opholdsområde og individuelt design.'),
(8, 'LOFT Suite', 4, 'Eksklusive suiter i to niveauer på øverste etage med udsigt over gårdhaverne og Søerne.');

